alter table schedule_exact_oracle_runs enable row level security;
create or replace function get_schedule_exact_oracle_problem_v1() returns jsonb language plpgsql stable security definer set search_path=public as $$declare outv jsonb;begin perform open_permission_context('schedule.generate');with tp as(select to_jsonb(t) j from schedule_time_profiles t where t.active and tenant_row_allowed(t.institution_code) order by t.updated_at desc limit 1),a as(select coalesce(jsonb_agg(jsonb_build_object('assignment_id',ta.id,'teacher_id',ta.teacher_id,'class_id',r.class_id,'course_id',r.course_id,'assigned_hours',ta.assigned_hours,'week_pattern',tm.week_pattern,'valid_from',tm.valid_from,'valid_to',tm.valid_to,'term_no',tm.term_no,'schedule_session_id',tm.schedule_session_id,'allowed_periods',tm.allowed_periods)),'[]'::jsonb) j from teacher_course_assignments ta join class_course_requirements r on r.id=ta.class_course_requirement_id join get_schedule_assignment_time_model_v1() tm on tm.assignment_id=ta.id where tenant_row_allowed(ta.institution_code)),l as(select coalesce(jsonb_agg(jsonb_build_object('assignment_id',teacher_assignment_id,'weekday',weekday,'period',period)),'[]'::jsonb) j from teacher_schedule where active and locked and tenant_row_allowed(institution_code)),u as(select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) j from teacher_unavailability x where active and tenant_row_allowed(institution_code)),pr as(select coalesce(jsonb_agg(jsonb_build_object('id',id,'relation_type',relation_type,'mode',mode,'weight',weight,'left_selector',left_selector,'right_selector',right_selector,'parameters',parameters)),'[]'::jsonb) j from schedule_planning_relations where active and mode<>'OFF' and tenant_row_allowed(institution_code)),sw as(select coalesce(jsonb_agg(jsonb_build_object('left_assignment_id',left_assignment_id,'right_assignment_id',right_assignment_id,'student_weight',student_weight,'severity_weight',severity_weight)),'[]'::jsonb) j from get_schedule_assignment_student_conflict_weights_v2()) select jsonb_build_object('schema','OKULOS_CP_SAT_ORACLE_V1','tenant',current_tenant_code(),'time_profile',coalesce((select j from tp),'{}'::jsonb),'assignments',(select j from a),'locked_rows',(select j from l),'teacher_unavailability',(select j from u),'planning_relations',(select j from pr),'student_conflict_weights',(select j from sw),'canonical_objective_order',jsonb_build_array('HARD','UNPLACED','MEDIUM','SOFT','LEGACY')) into outv;return outv;end$$;
create or replace function get_schedule_exact_oracle_health_v1() returns jsonb language plpgsql stable security definer set search_path=public as $$declare outv jsonb;begin perform open_permission_context('schedule.generate');select jsonb_build_object('total_runs',count(*),'optimal_runs',count(*) filter(where status='OPTIMAL'),'feasible_runs',count(*) filter(where status='FEASIBLE'),'unsupported_runs',count(*) filter(where status='UNSUPPORTED'),'latest',coalesce((select jsonb_build_object('status',r.status,'objective',r.objective,'best_bound',r.best_bound,'gap',r.gap,'wall_ms',r.wall_ms,'unsupported',r.unsupported,'created_at',r.created_at) from schedule_exact_oracle_runs r where r.institution_code=current_tenant_code() order by r.created_at desc limit 1),'{}'::jsonb)) into outv from schedule_exact_oracle_runs where institution_code=current_tenant_code();return outv;end$$;